ALTER TABLE public.user_profiles ADD COLUMN IF NOT EXISTS onboarding_policy_version text, ADD COLUMN IF NOT EXISTS onboarding_policy_accepted_at timestamptz;
ALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS mailing_address text;
CREATE FUNCTION public.save_workspace_business_settings(_ws uuid,_details jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE person text; account text; BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND account_type IN ('provider','facility','hospital')) THEN RAISE EXCEPTION 'Business settings unavailable'; END IF;
 IF length(coalesce(_details->>'display_name','')) NOT BETWEEN 1 AND 160 OR EXISTS(SELECT 1 FROM jsonb_each_text(_details) e WHERE e.key NOT IN ('display_name','legal_business_name','business_phone','dispatch_phone','business_address','mailing_address','operating_hours') OR length(e.value)>500) THEN RAISE EXCEPTION 'Invalid business settings'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 UPDATE public.workspaces SET display_name=btrim(_details->>'display_name'),legal_business_name=coalesce(nullif(btrim(_details->>'legal_business_name'),''),legal_business_name),business_phone=coalesce(nullif(btrim(_details->>'business_phone'),''),business_phone),dispatch_phone=coalesce(nullif(btrim(_details->>'dispatch_phone'),''),dispatch_phone),business_address=coalesce(nullif(btrim(_details->>'business_address'),''),business_address),mailing_address=coalesce(nullif(btrim(_details->>'mailing_address'),''),mailing_address),operating_hours=coalesce(nullif(btrim(_details->>'operating_hours'),''),operating_hours) WHERE id=_ws;
 SELECT mfn_id INTO person FROM public.user_profiles WHERE user_id=auth.uid(); SELECT mfn_id INTO account FROM public.workspaces WHERE id=_ws;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(_ws,'business_settings_saved',auth.uid(),person,account,jsonb_build_object('fields',(SELECT jsonb_agg(key) FROM jsonb_object_keys(_details) key)));
 END $$;
REVOKE ALL ON FUNCTION public.save_workspace_business_settings(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_workspace_business_settings(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.confirm_onboarding_policy(_version text,_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF _confirmed IS DISTINCT FROM true OR _version IS DISTINCT FROM '2026-11-07' OR NOT EXISTS(SELECT 1 FROM public.user_profiles p JOIN auth.users u ON u.id=p.user_id WHERE p.user_id=auth.uid() AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Setup unavailable'; END IF;
 UPDATE public.user_profiles SET onboarding_policy_version=_version,onboarding_policy_accepted_at=now() WHERE user_id=auth.uid() AND onboarding_policy_accepted_at IS NULL;
 IF FOUND THEN INSERT INTO public.account_security_audit(user_id,sender_mfn_id,event_type,result) SELECT auth.uid(),mfn_id,'onboarding_policy_acknowledged',_version FROM public.user_profiles WHERE user_id=auth.uid(); END IF; END $$;
REVOKE ALL ON FUNCTION public.confirm_onboarding_policy(text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.confirm_onboarding_policy(text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_onboarding_progress(_step integer,_complete boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.user_profiles; ws public.workspaces; BEGIN
 SELECT * INTO p FROM public.user_profiles WHERE user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND OR _step NOT BETWEEN 0 AND 4 OR p.status<>'active' OR p.is_test_account OR p.deleted_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Setup unavailable'; END IF;
 IF p.onboarding_completed_at IS NOT NULL THEN RETURN; END IF;
 IF (SELECT count(*) FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=auth.uid() AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account)<>1 THEN RAISE EXCEPTION 'Setup unavailable'; END IF;
 SELECT w.* INTO ws FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id WHERE m.user_id=auth.uid() AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account;
 IF _complete AND (nullif(btrim(p.first_name),'') IS NULL OR nullif(btrim(p.last_name),'') IS NULL OR nullif(btrim(p.phone),'') IS NULL OR p.onboarding_policy_accepted_at IS NULL OR (ws.account_type<>'private_pay' AND (nullif(btrim(ws.business_phone),'') IS NULL OR nullif(btrim(ws.business_address),'') IS NULL)) OR (ws.account_type='private_pay' AND NOT EXISTS(SELECT 1 FROM public.saved_patients WHERE owner_id=auth.uid() AND kind='patient' AND active))) THEN RAISE EXCEPTION 'Complete required profile details and policy acknowledgment'; END IF;
 UPDATE public.user_profiles SET onboarding_step=_step,onboarding_completed_at=CASE WHEN _complete THEN now() ELSE onboarding_completed_at END WHERE user_id=auth.uid(); END $$;
CREATE FUNCTION public.request_existing_account_connection(_ws uuid,_target uuid,_confirmed boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient text; kind text; invitation uuid; BEGIN
 IF _confirmed IS DISTINCT FROM true OR NOT public.can_manage_account_connections(_ws) OR _ws=_target OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND account_type IN ('private_pay','facility','hospital')) OR NOT EXISTS(SELECT 1 FROM public.search_business_identities('signed_in','') WHERE workspace_id=_target) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Connection unavailable'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 SELECT i.id INTO invitation FROM public.account_connection_invitations i WHERE i.inviter_workspace_id=_ws AND i.recipient_workspace_id=_target AND i.status='pending' AND i.expires_at>now() ORDER BY i.created_at DESC LIMIT 1; IF invitation IS NOT NULL THEN RETURN invitation; END IF;
 SELECT lower(u.email),CASE WHEN w.account_type='provider' THEN 'provider' ELSE 'facility' END INTO recipient,kind FROM public.workspace_members m JOIN auth.users u ON u.id=m.user_id JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_target AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND u.email_confirmed_at IS NOT NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL ORDER BY m.created_at LIMIT 1;
 IF recipient IS NULL THEN RAISE EXCEPTION 'Connection unavailable'; END IF;
 invitation:=public.manage_account_invitation(_ws,'send',NULL,recipient,kind,encode(gen_random_bytes(32),'hex'),true);
 UPDATE public.account_connection_invitations SET recipient_workspace_id=_target,delivery_status='not_sent' WHERE id=invitation;
 RETURN invitation; END $$;
REVOKE ALL ON FUNCTION public.request_existing_account_connection(uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_existing_account_connection(uuid,uuid,boolean) TO authenticated;
CREATE FUNCTION public.confirmed_usual_provider_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.preferred_provider_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.preferred_provider_id IS DISTINCT FROM OLD.preferred_provider_id) AND NOT EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND c.workspace_a=least(NEW.workspace_id,NEW.preferred_provider_id) AND c.workspace_b=greatest(NEW.workspace_id,NEW.preferred_provider_id)) THEN RAISE EXCEPTION 'Confirmed connection required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER confirmed_usual_provider BEFORE INSERT OR UPDATE ON public.account_relationship_preferences FOR EACH ROW EXECUTE FUNCTION public.confirmed_usual_provider_guard();
COMMENT ON COLUMN public.courses.private_file_path IS 'Authoritative private delivery object for the existing product. Prior private editions remain unused and retained; never publish these paths as asset URLs.';
COMMENT ON COLUMN public.user_profiles.onboarding_policy_accepted_at IS 'Setup acknowledgment only; never payment clickwrap, verification evidence or permission grant.';